      prisma,
      redisInstance,
      userStore,
      cfg.AI_GATEWAY_API_KEY
    );
    const { ProviderService } = await import("@/providers/index.ts");

    const providers = new ProviderService({
      apiKeys: {
        anthropic: cfg.ANTHROPIC_API_KEY,
        gemini: cfg.GOOGLE_API_KEY,
        grok: cfg.X_AI_KEY,
